class InPlaceAmountSorter {

    private static final Logger log = Logger.getLogger(InPlaceAmountSorter.class.getName());

    void sort(int[] a) {
        int n = a.length;

        // Phase 1: build a max-heap by sifting down every non-leaf, last parent → root.
        for (int i = n / 2 - 1; i >= 0; i--) {
            siftDown(a, i, n);
        }
        log.fine(() -> "  heap built, max at root = " + a[0]);

        // Phase 2: repeatedly move the max (root) to the end, shrink, re-heapify.
        for (int end = n - 1; end > 0; end--) {
            swap(a, 0, end);                 // largest goes to its final slot
            siftDown(a, 0, end);             // restore heap over a[0..end-1]
        }
    }

    // Sift a[i] down within the active heap of size 'size'.
    private void siftDown(int[] a, int i, int size) {
        while (true) {
            int left = 2 * i + 1, right = 2 * i + 2, largest = i;
            if (left < size && a[left] > a[largest]) largest = left;
            if (right < size && a[right] > a[largest]) largest = right;
            if (largest == i) return;        // heap property restored
            swap(a, i, largest);
            i = largest;                     // continue sinking
        }
    }

    private void swap(int[] a, int i, int j) {
        int tmp = a[i]; a[i] = a[j]; a[j] = tmp;
    }
}

